// npm install express express-session express-rate-limit bcrypt
const express = require('express');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
  },
}));

const users = new Map(); // username -> { id, passwordHash }

// Compared against when the username is unknown, so response time does not reveal which usernames exist.
const DUMMY_HASH = bcrypt.hashSync('dummy', 12);

// Only failed responses (status >= 400) count toward the limit.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed login attempts. Try again later.' },
});

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || password.length < 8) {
    return res.status(400).json({ error: 'Username and a password of at least 8 characters are required.' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'Username is taken.' });
  }
  users.set(username, { id: users.size + 1, passwordHash: await bcrypt.hash(password, 12) });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Username and password are required.' });
  }
  const user = users.get(username);
  const ok = await bcrypt.compare(password, user ? user.passwordHash : DUMMY_HASH);
  if (!user || !ok) {
    return res.status(401).json({ error: 'Invalid username or password.' });
  }
  // A fresh session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: 'Login failed.' });
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res) => {
  req.session.destroy(() => {
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not logged in.' });
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

app.listen(3000);
```

I have not run this, and it needs `SESSION_SECRET` set in the environment.

- **Storage:** users, sessions and rate-limit counters all live in memory, so swap in a database and a shared store (e.g. Redis) before production or running more than one instance.
- **Rate limiting:** the limit is per IP only, so add a per-account lockout if distributed guessing against a single account is a concern, and set `trust proxy` if you sit behind a reverse proxy, or every client shares one IP.
- **CSRF:** there is no CSRF protection beyond `sameSite: 'lax'`, so add it before you serve browser forms that change state.
